using System.Text;
using OpenApiSentinel.Core;

namespace OpenApiSentinel.Reporting;

/// <summary>Single-file, offline Compare HTML report. Its aggregation is presentation-only.</summary>
public sealed class HtmlReporter : IResultReporter
{
    public string FormatName => "html";

    public string Render(ComparisonResult result, ReporterOptions options)
    {
        var model = HtmlPresentation.Build(result);
        var localizer = new HtmlLocalizer(options.HtmlLanguage);
        var writer = new StringBuilder(64 * 1024);
        var passed = !result.PolicyViolated;

        writer.AppendLine("<!DOCTYPE html>");
        writer.AppendLine($"<html lang=\"{(localizer.IsChinese ? "zh-Hant-TW" : "en")}\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">");
        writer.AppendLine($"<title>OpenAPI Sentinel — {Escape(result.OldContractName)} → {Escape(result.NewContractName)}</title>{Styles}</head><body><header class=\"topbar\"><div class=\"wrap brand\">🛡 <b>OpenAPI Sentinel</b><span>{Escape(localizer.T("API 相容性報告", "API Compatibility Report"))}</span><strong class=\"verdict {(passed ? "pass" : "fail")}\">{Escape(passed ? localizer.T("通過", "PASSED") : localizer.T("未通過", "FAILED"))}</strong></div></header><main class=\"wrap\">");
        HeaderAndSummary(writer, result, model, passed, localizer);
        Changes(writer, result, options, model, localizer);
        writer.AppendLine($"<footer>{Escape(localizer.T("由 OpenAPI Sentinel 產生。離線、可重現的合約分析。", "Generated by OpenAPI Sentinel — deterministic, offline contract analysis."))}</footer></main>{Script}</body></html>");
        return writer.ToString();
    }

    private static void HeaderAndSummary(StringBuilder writer, ComparisonResult result, HtmlReportModel model, bool passed, HtmlLocalizer localizer)
    {
        writer.AppendLine("<section class=\"card report-header\"><div class=\"info-list\">");
        InfoRow(writer, localizer.T("結果", "Result"), $"<span class=\"badge {(passed ? "ok" : "bad")}\">{Escape(passed ? localizer.T("通過", "PASSED") : localizer.T("未通過", "FAILED"))}</span>");
        InfoRow(writer, localizer.T("舊版合約", "Old contract"), $"<span class=\"mono\">{Escape(result.OldContractName)}</span>{Spec(result.OldOpenApiVersion, result.OldInfoVersion, localizer)}");
        InfoRow(writer, localizer.T("新版合約", "New contract"), $"<span class=\"mono\">{Escape(result.NewContractName)}</span>{Spec(result.NewOpenApiVersion, result.NewInfoVersion, localizer)}");
        var taipei = result.GeneratedAtUtc.ToOffset(TimeSpan.FromHours(8));
        InfoRow(writer, localizer.T("產生時間", "Generated time"), $"{taipei:yyyy-MM-dd HH:mm:ss} {Escape(localizer.T("（台北 UTC+8）", "(Taipei UTC+8)"))}");
        writer.AppendLine("</div><div class=\"summary-line\"><b>" + Escape(localizer.T("本次變更摘要", "Change summary")) + ":</b> " +
            $"<span>🔴 {Escape(localizer.T("需要立即處理", "Needs immediate attention"))}: {model.Immediate.Count}</span> " +
            $"<span>🟠 {Escape(localizer.T("建議確認", "Needs review"))}: {model.Review.Count}</span> " +
            $"<span>🟢 {Escape(localizer.T("一般變更", "General changes"))}: {model.General.Count}</span></div></section>");
    }

    private static void InfoRow(StringBuilder writer, string label, string value) =>
        writer.AppendLine($"<div class=\"info-row\"><span class=\"lbl\">{Escape(label)}：</span><span class=\"val\">{value}</span></div>");

    private static string Spec(string? specification, string? apiVersion, HtmlLocalizer localizer)
    {
        var values = new List<string>();
        if (!string.IsNullOrWhiteSpace(specification)) values.Add("spec " + Escape(specification));
        if (!string.IsNullOrWhiteSpace(apiVersion))
        {
            var displayVersion = apiVersion.StartsWith('v') || apiVersion.StartsWith('V') ? apiVersion : "v" + apiVersion;
            values.Add(Escape(localizer.T("API 版本 ", "API ")) + Escape(displayVersion));
        }

        return values.Count == 0 ? "" : " <small>· " + string.Join(" · ", values) + "</small>";
    }

    private static void Changes(StringBuilder writer, ComparisonResult result, ReporterOptions options, HtmlReportModel model, HtmlLocalizer localizer)
    {
        writer.AppendLine($"<section class=\"card changes\"><h2>{Escape(localizer.T("變更項目", "Changes"))}</h2><div class=\"filters\"><input id=\"search\" type=\"search\" placeholder=\"{Escape(localizer.T("搜尋路徑、規則或變更內容…", "Search path, rule, explanation…"))}\"><select id=\"f-group\"><option value=\"\">{Escape(localizer.T("全部", "All"))}</option><option value=\"immediate\">{Escape(localizer.T("需要立即處理", "Needs immediate attention"))}</option><option value=\"review\">{Escape(localizer.T("建議確認", "Needs review"))}</option><option value=\"general\">{Escape(localizer.T("一般變更", "General changes"))}</option></select><button type=\"button\" id=\"expand\">{Escape(localizer.T("全部展開", "Expand all"))}</button><button type=\"button\" id=\"collapse\">{Escape(localizer.T("全部收合", "Collapse all"))}</button></div><p id=\"visible-count\" data-template=\"{Escape(localizer.T("顯示 {0} 個變更", "Showing {0} changes"))}\"></p><div id=\"findings\">");
        foreach (var finding in model.Findings) Card(writer, finding, localizer);
        if (options.IncludeSuppressed && result.Suppressed.Count > 0)
        {
            writer.AppendLine($"<details class=\"suppressed\"><summary><b>{Escape(localizer.T("已抑制項目", "Suppressed findings"))} ({result.Suppressed.Count})</b></summary><ul>{string.Join("", result.Suppressed.Select(x => $"<li>{Escape(x.Finding.RuleId)} · {Escape(x.Reason)}</li>"))}</ul></details>");
        }

        writer.AppendLine("</div></section>");
    }

    private static void Card(StringBuilder writer, HtmlFinding item, HtmlLocalizer localizer)
    {
        var finding = item.Finding;
        var searchText = Escape($"{finding.Path} {finding.Location} {finding.RuleId} {finding.Title} {localizer.Short(item)} {localizer.Explanation(finding)}".ToLowerInvariant());
        writer.AppendLine($"<details class=\"finding\" data-group=\"{item.Group.ToDataValue()}\" data-text=\"{searchText}\"><summary><span class=\"severity\">{Escape(finding.Severity.ToString().ToUpperInvariant())}</span><span class=\"mono\">{Escape(Name(finding.Path, finding.HttpMethod))}</span><span>{Escape(localizer.Short(item))}</span><span class=\"compat\">{Escape(localizer.GroupLabel(item.Group))}</span></summary><div class=\"body\"><p><b>{Escape(localizer.Title(finding))}</b> <small>· {Escape(finding.RuleId)} · {Escape(finding.ChangeType.ToString())}</small></p><p>{Escape(localizer.Explanation(finding))}</p>");
        if (finding.OldValue is not null || finding.NewValue is not null)
        {
            writer.AppendLine($"<div class=\"values\"><div><span class=\"lbl\">{Escape(localizer.T("更新前", "Before"))}</span><pre>{Escape(finding.OldValue ?? "(none)")}</pre></div><div><span class=\"lbl\">{Escape(localizer.T("更新後", "After"))}</span><pre>{Escape(finding.NewValue ?? "(removed)")}</pre></div></div>");
        }

        writer.AppendLine($"<div class=\"grid\"><div><span class=\"lbl\">{Escape(localizer.T("影響", "Impact"))}</span><p>{Escape(localizer.Impact(finding))}</p></div><div><span class=\"lbl\">{Escape(localizer.T("建議處理方式", "Suggested action"))}</span><p>{Escape(localizer.Action(finding))}</p></div></div></div></details>");
    }

    private static string Name(string path, HttpMethodKind method) => string.IsNullOrEmpty(method.ToHttpString()) ? (string.IsNullOrEmpty(path) ? "(document)" : path) : method.ToHttpString() + " " + path;

    private static string Escape(string? value) => (value ?? "").Replace("&", "&amp;", StringComparison.Ordinal).Replace("<", "&lt;", StringComparison.Ordinal).Replace(">", "&gt;", StringComparison.Ordinal).Replace("\"", "&quot;", StringComparison.Ordinal).Replace("'", "&#39;", StringComparison.Ordinal);

    private const string Styles = """
<style>:root{--bg:#f6f8fa;--card:#fff;--ink:#1f2328;--muted:#656d76;--line:#d8dee4;--red:#cf222e;--orange:#bc4c00;--green:#1a7f37}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1240px;margin:auto;padding:0 20px}.topbar{background:#10151c;color:#fff;padding:14px 0}.brand{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.brand span,small,.lbl,footer{color:var(--muted);font-size:12px}.verdict{margin-left:auto;padding:4px 12px;border-radius:999px}.pass,.ok{color:var(--green);background:#dafbe1}.fail,.bad{color:var(--red);background:#ffebe9}main{display:grid;gap:16px;padding-top:22px;padding-bottom:35px}.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:17px}.info-list{display:grid;gap:9px}.info-row{display:flex;align-items:baseline;gap:7px}.info-row .lbl{min-width:96px;text-transform:none;letter-spacing:0}.val{font-weight:600;overflow-wrap:anywhere}.summary-line{margin-top:15px;padding-top:14px;border-top:1px solid var(--line);display:flex;gap:12px;flex-wrap:wrap}.summary-line span{white-space:nowrap}.badge,.severity,.compat{padding:3px 9px;border-radius:999px;font-weight:700;font-size:12px}.mono,pre{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}.grid,.values{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}h2{font-size:18px;margin:0 0 12px}details{border:1px solid var(--line);border-radius:8px;margin:8px 0;background:#fff}summary{cursor:pointer;padding:10px;display:flex;gap:9px;align-items:center;flex-wrap:wrap}.finding summary .compat{margin-left:auto;background:#eaeef2}.body{border-top:1px solid var(--line);padding:10px 14px}.body p{margin:6px 0}.values pre{white-space:pre-wrap;background:var(--bg);padding:8px;margin:4px 0}.filters{display:flex;gap:8px;flex-wrap:wrap;position:sticky;top:0;background:var(--card);padding:6px 0}input,select,button{font:inherit;padding:7px 9px;border:1px solid var(--line);border-radius:7px;background:#fff}input{flex:1 1 260px}footer{text-align:center}@media(max-width:650px){.wrap{padding:0 12px}.values,.grid{grid-template-columns:1fr}.info-row{align-items:flex-start;flex-direction:column;gap:0}.brand{align-items:flex-start}.finding summary .compat{margin-left:0}}@media print{.topbar{background:#fff;color:#000}.filters,button{display:none}details{break-inside:avoid}}</style>
""";

    private const string Script = """
<script>(()=>{const q=document.querySelector('#search'),g=document.querySelector('#f-group'),cards=[...document.querySelectorAll('.finding')],count=document.querySelector('#visible-count');function apply(){let n=0;cards.forEach(x=>{const ok=(!q.value||x.dataset.text.includes(q.value.toLowerCase()))&&(!g.value||x.dataset.group===g.value);x.hidden=!ok;if(ok)n++});count.textContent=count.dataset.template.replace('{0}',n)}q?.addEventListener('input',apply);g?.addEventListener('change',apply);document.querySelector('#expand')?.addEventListener('click',()=>document.querySelectorAll('details').forEach(x=>x.open=true));document.querySelector('#collapse')?.addEventListener('click',()=>document.querySelectorAll('details').forEach(x=>x.open=false));apply()})()</script>
""";
}
